{
  "name": "AG-UC2 两轴压电微步运动控制器",
  "name_en": "AG-UC2 Two-Axis Piezo Motion Controller",
  "manufacturer": "Newport",
  "description": "这是一台用于驱动两路微位移轴的运动控制器，可控制 X/Y 两个轴进行相对步进、连续点动、限位移动与零点设定，并支持步幅和步延时等参数设置。它常用于光学对准、精密微位移调整和实验平台上的双轴定位任务。",
  "description_en": "This is a two-axis motion controller for driving micro-positioning axes. It controls X and Y axes for relative stepping, continuous jogging, motion toward limits, and zero-position definition, with adjustable step amplitude and step delay. It is commonly used for optical alignment, precision micro-positioning, and dual-axis positioning tasks in laboratory setups.",
  "tag_hints": [
    "two-axis motion control",
    "piezo step motor",
    "micro-positioning",
    "optical alignment",
    "jog motion",
    "relative step move",
    "serial control"
  ],
  "actions": [
    {
      "action_name": "auto-axis",
      "description": "选择或访问控制器上的某个运动轴。",
      "description_en": "Select or access one motion axis on the controller."
    },
    {
      "action_name": "auto-enable_remote_mode",
      "description": "启用控制器的远程控制模式。",
      "description_en": "Enable the controller's remote-control mode."
    },
    {
      "action_name": "auto-error_previous_command",
      "description": "获取上一条命令的错误状态。",
      "description_en": "Get the error status of the previous command."
    },
    {
      "action_name": "auto-firmware_version",
      "description": "获取固件版本。",
      "description_en": "Get the firmware version."
    },
    {
      "action_name": "auto-limit_status",
      "description": "获取限位状态。",
      "description_en": "Get the limit status."
    },
    {
      "action_name": "auto-sleep_time",
      "description": "获取或设置休眠时间。",
      "description_en": "Get or set the sleep time."
    },
    {
      "action_name": "auto-reset_controller",
      "description": "重置控制器。",
      "description_en": "Reset the controller."
    },
    {
      "action_name": "auto-ag_sendcmd",
      "description": "向控制器发送原始命令。",
      "description_en": "Send a raw command to the controller."
    },
    {
      "action_name": "auto-ag_query",
      "description": "向控制器发送原始查询并读取响应。",
      "description_en": "Send a raw query to the controller and read the response."
    },
    {
      "action_name": "auto-axis_status",
      "description": "获取轴状态。",
      "description_en": "Get the axis status."
    },
    {
      "action_name": "auto-jog",
      "description": "使所选轴以点动模式连续运动。",
      "description_en": "Jog the selected axis in a continuous jog mode."
    },
    {
      "action_name": "auto-number_of_steps",
      "description": "获取或设置步数。",
      "description_en": "Get or set the number of steps."
    },
    {
      "action_name": "auto-move_relative",
      "description": "使所选轴按相对步数移动。",
      "description_en": "Move the selected axis by a relative number of steps."
    },
    {
      "action_name": "auto-move_to_limit",
      "description": "使所选轴朝限位方向移动直到到达限位。",
      "description_en": "Move the selected axis toward a limit until the limit is reached."
    },
    {
      "action_name": "auto-step_amplitude",
      "description": "获取或设置步进幅度。",
      "description_en": "Get or set the step amplitude."
    },
    {
      "action_name": "auto-step_delay",
      "description": "获取或设置步进延时。",
      "description_en": "Get or set the step delay."
    },
    {
      "action_name": "auto-am_i_still",
      "description": "获取轴是否已停止运动。",
      "description_en": "Get whether the axis has stopped moving."
    },
    {
      "action_name": "auto-zero_position",
      "description": "将当前位置定义为零点。",
      "description_en": "Define the current position as zero."
    }
  ]
}

